    private void listarVendidos(){
        ProdutosDAO produtosdao = new ProdutosDAO();

        DefaultTableModel model = (DefaultTableModel) listaVendas.getModel();
        model.setNumRows(0);

        ArrayList<ProdutosDTO> lista_vendidos = produtosdao.listarProdutosVendidos();

        for (ProdutosDTO produto : lista_vendidos) {
            model.addRow(new Object[]{
                produto.getId(),
                produto.getNome(),
                produto.getValor(),
                produto.getStatus()
            });
        }
    }
